     9	export function useAgentCanvasBridge(descriptor: Omit<CanvasDescriptor, 'canvasId' | 'stableWorkspaceId'>, handle: (command: CanvasCommand) => Promise<unknown>, workspace?: CanvasWorkspace, canMutate: () => boolean = () => true) {
    10	  const [agentStatus, setAgentStatus] = useState<LiveAgentStatus>({ connected: false, count: 0 });
    11	  const [canvasId] = useState(() => crypto.randomUUID());
    12	  const [identity, setIdentity] = useState<{ stableWorkspaceId?: string }>();
    13	  useEffect(() => {
    14	    let active = true;
    15	    void browserStableWorkspaceId(import.meta.env.BASE_URL).then(stableWorkspaceId => {
    16	      if (active) setIdentity({ stableWorkspaceId });
    17	    });
    18	    return () => { active = false; };
    19	  }, []);
    20	  const latest = useRef({ descriptor, handle, canMutate }); latest.current = { descriptor, handle, canMutate };
    21	  const registration = identity && JSON.stringify({ ...descriptor, canvasId, ...identity });
    22	  useEffect(() => {
    23	    if (!registration) return;
    24	    void apiFetch('/api/mapping/agent/canvases', { method: 'POST', headers: { 'content-type': 'application/json' }, body: registration }).catch(() => undefined);
    25	  }, [registration]);
    26	  useEffect(() => {
    27	    if (!identity) return;
    28	    const abort = new AbortController();
    29	    let timer: ReturnType<typeof setTimeout> | undefined;
    30	    const results = new Map<string, { value?: unknown; error?: string }>();
    31	    const request = async (path: string, body?: unknown, method = body === undefined ? 'GET' : 'POST') => {
    32	      const response = await apiFetch(`/api/mapping/agent${path}`, { method, signal: abort.signal,
    33	        ...(body === undefined ? {} : { headers: { 'content-type': 'application/json' }, body: JSON.stringify(body) }) });
    34	      if (!response.ok) throw await errorFrom(response);
    35	      return response.json();
    36	    };
    37	    const register = () => request('/canvases', { ...latest.current.descriptor, canvasId, ...identity });
    38	    const run = async () => {
    39	      try {
    40	        await register();
    41	        while (!abort.signal.aborted) {
    42	          const commands: CanvasCommand[] = await request(`/canvases/${canvasId}/commands`);
    43	          for (const command of commands) {
    44	            const started = performance.now();
    45	            let result = results.get(command.id);
    46	            if (!result) {
    47	              try { result = { value: await latest.current.handle(command) }; }
    48	              catch (error) { result = { error: error instanceof Error ? error.message : String(error) }; }
    49	              if (mutationCommands.has(command.method)) results.set(command.id, result);
    50	              if (results.size > 200) results.delete(results.keys().next().value!);
    51	            }
    52	            const handled = performance.now();
    53	            const reply = canvasReply(command, result);
    54	            const encoded = performance.now();
    55	            const response = await apiFetch(`/api/mapping/agent/canvases/${canvasId}/reply`, { method: 'POST', signal: abort.signal,
    56	              headers: { 'content-type': 'application/json', 'x-canvas-command-id': command.id }, body: reply.body });
    57	            if (!response.ok) {
    58	              // A proxy/backend can enforce a lower limit. Resolve the pending command immediately.
    59	              await request(`/canvases/${canvasId}/reply`, { commandId: command.id,
    60	                error: `CANVAS_REPLY_REJECTED: method=${command.method} actualBytes=${reply.bytes} status=${response.status}; retry the identical requestId if this was a mutation` });
    61	            }
    62	            console.debug('canvas-reply', { method: command.method, bytes: reply.bytes, handleMs: Math.round(handled - started), encodeMs: Math.round(encoded - handled), replyMs: Math.round(performance.now() - encoded), durationMs: Math.round(performance.now() - started), oversized: reply.oversized });
    63	          }
    64	          await register();
    65	        }
    66	      } catch {
    67	        if (!abort.signal.aborted) timer = setTimeout(() => void run(), 1000);
    68	      }
    69	    };
    70	    void run();
    71	    const unregister = () => { void apiFetch(`/api/mapping/agent/canvases/${canvasId}`, { method: 'DELETE', keepalive: true }).catch(() => undefined); };
    72	    // React cleanup does not run on page reload. Retire this ephemeral instance
    73	    // promptly, without ever deleting a replacement that has the same stable ID.
    74	    window.addEventListener('pagehide', unregister);
    75	    return () => { abort.abort(); clearTimeout(timer); window.removeEventListener('pagehide', unregister); unregister(); };
    76	  }, [canvasId, identity]);
    77	  useEffect(() => {
    78	    setAgentStatus({ connected: false, count: 0 });
    79	    if (!workspace || !identity) return;
    80	    const endpoint = new URL(`${import.meta.env.BASE_URL.replace(/\/$/, '')}/api/mapping/live`, location.href);
    81	    endpoint.protocol = endpoint.protocol === 'https:' ? 'wss:' : 'ws:';
    82	    return publishLiveCanvasSelections(workspace, canvasId, endpoint.href, setAgentStatus, () => latest.current.canMutate());
    83	  }, [workspace, canvasId, identity]);
    84	  return { canvasId, agentStatus };
    85	}
