    29	export function scaleCanvasTransform(
    30	  transform: CanvasTransform,
    31	  requestedScale: number,
    32	  anchor: CanvasPoint
    33	): CanvasTransform {
    34	  const scale = clampDiagramCanvasScale(requestedScale);
