    44	
    45	export function canvasPinchGeometry(
    46	  first: CanvasPoint,
    47	  second: CanvasPoint
    48	): CanvasPinchGeometry | null {
    49	  const dx = second.x - first.x;
    50	  const dy = second.y - first.y;
    51	  const distance = Math.hypot(dx, dy);
    52	  if (distance < 1) return null;
    53	  return {
    54	    center: {
    55	      x: (first.x + second.x) / 2,
    56	      y: (first.y + second.y) / 2
    57	    },
    58	    distance
    59	  };
    60	}
