    67	    startDistance: geometry.distance,
    68	    startScale: transform.scale,
    69	    contentPoint: {
    70	      x: (geometry.center.x - transform.offset.x) / transform.scale,
    71	      y: (geometry.center.y - transform.offset.y) / transform.scale
