197	  if (transaction.discarded || transaction.applied === redo) return false;
198	  const expected = canvasId === transaction.sourceId ? redo ? transaction.sourceBefore : transaction.sourceAfter
199	    : canvasId === transaction.destinationId ? redo ? transaction.destinationBefore : transaction.destinationAfter : undefined;
200	  return record.headId === expected;
201	}
202	export function prepareTransferNavigation(sourceRecord: CanvasHistoryRecord, destinationRecord: CanvasHistoryRecord, transaction: CanvasTransfer, redo = false) {
203	  if (!transferBoundary(sourceRecord, transaction, transaction.sourceId, redo) || !transferBoundary(destinationRecord, transaction, transaction.destinationId, redo))
204	    throw Error('Undo newer edits in both participating canvases before undoing or redoing this transfer.');
205	  const source = new CanvasHistory(documentFromHistory(sourceRecord), {}, sourceRecord), destination = new CanvasHistory(documentFromHistory(destinationRecord), {}, destinationRecord);
206	  if (transaction.mode === 'move' && !source.navigate(redo)) throw Error('Source transfer checkpoint is unavailable');
207	  if (!destination.navigate(redo)) throw Error('Destination transfer checkpoint is unavailable');
208	  return { source: state(source), destination: state(destination), transaction: { ...transaction, applied: redo } };
209	}

