166	  private async syncDirectory(directory: string) {
167	    const dir = await open(directory, 'r'); try { await dir.sync(); } finally { await dir.close(); }
168	  }
169	  private async atomic(file: string, text: string, syncDirectory = true) {
170	    await mkdir(path.dirname(file), { recursive: true });
171	    const temp = `${file}.${randomUUID()}.tmp`;
172	    try {
173	      const handle = await open(temp, 'wx');
174	      try { await handle.writeFile(text); await handle.sync(); } finally { await handle.close(); }
175	      await rename(temp, file);
176	      if (syncDirectory) await this.syncDirectory(path.dirname(file));
177	    } finally { await rm(temp, { force: true }); }
178	  }
179	  private async publish(manifest: Manifest, records: WorkspaceRecords, keys: string[]) {
180	    const directory = path.join(this.root, 'workspace-records');
181	    let cursor = 0;
182	    // Bound open files and serialization memory, while overlapping durable writes.
183	    // Wait for every writer even on failure: no work may outlive this transaction.
184	    const results = await Promise.allSettled(Array.from({ length: Math.min(8, keys.length) }, async () => {
185	      while (cursor < keys.length) {
186	        const key = keys[cursor++];
187	        if (!Object.hasOwn(records, key)) { delete manifest.records[key]; continue; }
188	        const text = JSON.stringify(records[key]), id = hash(text);
189	        if (manifest.records[key] !== id) {
190	          const file = path.join(directory, id + '.json');
191	          try { if (await readFile(file, 'utf8') !== text) throw Error('Workspace record integrity failure'); }
192	          catch (e) { if ((e as NodeJS.ErrnoException).code !== 'ENOENT') throw e; await this.atomic(file, text, false); }
193	          manifest.records[key] = id;
194	        }
195	      }
196	    }));
197	    for (const result of results) if (result.status === 'rejected') throw result.reason;
198	    // Make every blob's directory entry durable before publishing references to it.
199	    // This also covers blobs left behind by an interrupted earlier attempt.
200	    if (keys.some(key => Object.hasOwn(records, key))) await this.syncDirectory(directory);
201	    const raw = JSON.stringify(manifest);
202	    await this.atomic(this.file, raw);
203	    return this.cached = { raw, manifest, records, historyValidation: 'current' };
204	  }
205	}

